package com.cpf.starter.tcp;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public final class CpfTcpUnknownResultStore {private final ConcurrentHashMap<String,CpfTcpUnknownResult> values=new ConcurrentHashMap<>();private final int limit;public CpfTcpUnknownResultStore(int limit){this.limit=limit;}public void record(CpfTcpUnknownResult v){if(values.size()>=limit&&!values.containsKey(v.correlationId()))throw new IllegalStateException("UNKNOWN_RESULT store limit reached");values.put(v.correlationId(),v);}public Optional<CpfTcpUnknownResult> find(String id){return Optional.ofNullable(values.get(id));}public boolean reconcile(String id){return values.remove(id)!=null;}public List<CpfTcpUnknownResult> snapshot(){return values.values().stream().sorted(java.util.Comparator.comparing(CpfTcpUnknownResult::writtenAt)).toList();}}
